from lib import *
S = SS('e8')
steps = [
    step("同样的 2 万条 products,行式(JSON Lines)与列式(每个字段一个 JSON 数组,按列拼接)。原始字节:行式 7214161,列式 4994174(列式不重复写键名)。压缩后:gzip-6 行式 1484671、列式 937295;lz4 行式 2314121、列式 1716426;zstd-3 行式 1331194、列式 889278;zstd-19 行式 1047098、列式 752806。列式 zstd-3 比行式小 33.2%,gzip 小 36.9%,lz4 小 25.8%。键名重复不是全部原因——压缩后仍然小这么多,是因为同一列的值挨在一起。", t=tl(S(1)), done=lidx(S(1), '列式(JSON 数组)'), mark=lidx(S(1), '行式 JSON Lines'), b=bars([['行式 zstd-3', 1331194, '1331194'], ['列式 zstd-3', 889278, '889278'], ['行式 zstd-19', 1047098, '1047098'], ['列式 zstd-19', 752806, '752806']], 1340000, mark=[0, 2], done=[1, 3]), kv=KV([['行式 → 列式(zstd-3)', '1331194 → 889278,小 33.2%'], ['gzip-6', '小 36.9%'], ['lz4', '小 25.8%']], ['行式 → 列式(zstd-3)'])),
    step("每一列单独压缩(zstd-3):id 160001 → 8886(18.01×);url 1135001 → 11989(94.67×);currency 19.04×;category 12.87×;tags 6.56×;seller_name 6.18×;updated_at 4.59×;rating 3.94×;title 1223717 → 413803,只有 2.96×,占行式压缩后总量的 31.1%;price 2.37×,stock 2.41×,seller_id 2.33×。各列压缩后相加 879905 字节,整个列式拼起来一起压缩 889278,行式 1331194。压缩后的字节几乎都花在 title(随机拼的词)和那些没有规律的数字上;url、id、currency、category 几乎白送。", t=tl(S(2)), done=lidx(S(2), 'title'), mark=lidx(S(2), 'url '), b=bars([['title 压缩后', 413803, '413803'], ['tags 压缩后', 123723, '123723'], ['updated_at 压缩后', 100143, '100143'], ['price 压缩后', 49891, '49891'], ['url 压缩后', 11989, '11989']], 420000, mark=[0], done=[4]), kv=KV([['url', '94.67×,几乎不占空间'], ['title', '2.96×,占 31.1%'], ['各列压缩后相加', '879905,整个列式一起压 889278']], ['title'])),
    step("记录的排列顺序也影响压缩(zstd-3)。行式:原顺序(按 id)1331194;按 category 排序 1297197;按 seller.id 排序 1328172;按 title 排序 1339855;随机打乱 1350892。列式:原顺序 889278;按 category 排序 972869;按 seller.id 排序 972163;按 title 排序 991309;随机打乱 1000771。按 category 排序让行式小了 2.6%,但让列式大了 9.4%——原顺序里 id 连续、url 里的数字递增,这些规律被排序打乱。排序有没有用取决于你排的那个字段占不占大头。", t=tl(S(3)), done=lidx(S(3), '按 category 排序'), mark=lidx(S(3), '随机打乱'), b=bars([['行式:原顺序', 1331194, '1331194'], ['行式:按 category', 1297197, '1297197'], ['列式:原顺序', 889278, '889278'], ['列式:按 category', 972869, '972869']], 1340000, done=[1, 2], mark=[3]), kv=KV([['行式按 category 排序', '小 2.6%'], ['列式按 category 排序', '大 9.4%(id、url 的规律被打乱)'], ['随机打乱', '行式 1350892,列式 1000771']], ['列式按 category 排序'])),
    step("列式加上针对每一列的编码(手工做的简化列存):id 差分 + varint 20002 字节,zstd 后只有 21;url 只保留 ? 之后的部分 334999 → 159;title 1183715 → 409620;price 存整数分 41136 → 39571;currency 字典 2 项 20008 → 3634;category 字典 30 项 20616 → 13170;seller_name 字典 795 项 46155 → 33606;tags 字典 60 项 60652 → 45164;updated_at 存 Unix 秒 100000 → 70849;stock、rating、seller_id 各约 2–3 万字节压缩后 1–3 万。合计编码后 1918979 字节,逐列再 zstd-3 共 685160 字节——对比行式 JSON Lines zstd-3 的 1331194,小了 48.5%;列式 JSON zstd-3 是 889278。", t=tl(S(4)), done=lidx(S(4), '合计 编码后'), mark=lidx(S(4), 'id(差分 + varint)'), b=bars([['行式 JSON Lines zstd-3', 1331194, '1331194'], ['列式 JSON zstd-3', 889278, '889278'], ['列存 + 专用编码 + zstd-3', 685160, '685160']], 1340000, mark=[0], done=[2]), kv=KV([['id 列', '20002 → 21 字节(差分后全是 1)'], ['url 列', '334999 → 159 字节'], ['合计', '685160 字节,比行式小 48.5%']], ['合计'])),
    step("分块:每块 N 条,行式与列式各自压缩(zstd-3)。每块 100 条:行式 1746783,列式 1548566,列式小 11.3%;1000 条:1421724 对 1147083,小 19.3%;5000 条:1344906 对 925128,小 31.2%;全部 20000 条:1331194 对 889278,小 33.2%。块越小,列式的优势越小——一块里每一列的重复值就少了。需要随机访问而切小块的时候,列存的好处会打折扣。", t=tl(S(5)), done=lidx(S(5), '    20000'), mark=lidx(S(5), '      100'), b=bars([['每块 100 条:列式比行式小 %', 11.3, '11.3'], ['每块 1000 条', 19.3, '19.3'], ['每块 5000 条', 31.2, '31.2'], ['每块 20000 条', 33.2, '33.2']], 35, mark=[0], done=[3]), kv=KV([['每块 100 条', '列式只小 11.3%'], ['每块 1000 条', '小 19.3%'], ['整个文件一块', '小 33.2%']], ['每块 100 条'])),
    step("只读 price 一列(2 万条,各 7 次中位数,结果都是 1105543.79):行式要解压整个文件(读入 1331194 字节)再逐行 json.loads,中位 57.7 ms;列式只解压 price 那一列(读入 49891 字节)再 json.loads,中位 1.3 ms。列式读一列少读 96%(49891 对 1331194)的数据、快 44 倍。这是列存格式(如 Parquet)主要的卖点:压缩更好、读一列更便宜。", t=tl(S(6)), done=lidx(S(6), '列式:只解压 price 列'), mark=lidx(S(6), '行式:解压全部'), b=bars([['行式:读入字节', 1331194, '1331194'], ['列式:读入字节', 49891, '49891']], 1340000, mark=[0], done=[1]), kv=KV([['行式读一列', '57.7 ms,读入 1331194 字节'], ['列式读一列', '1.3 ms,读入 49891 字节'], ['代价', '写入、按行读取、更新都更麻烦']], ['列式读一列'])),
]
A = mkarte('e8', 8, '编码,列式存储,行式,压缩,字典编码,差分,zstd,Parquet,Python,真实验证,动画演示',
    '同样的数据换一种排列:列式比行式 zstd-3 小 33.2%;每列单独看,url 能压 94.67×、title 只有 2.96×;给每列配专用编码(字典、差分、整数分)再压缩共 685160 字节,比行式小 48.5%;读 price 一列只要 1.3 ms 对 57.7 ms;分块越小列式优势越小。',
    '同样的数据,按列存比按行存压缩得小得多。这是“高压缩比”最重要的来源之一:让相似的值挨在一起。这篇把行式和列式、排列顺序、每列专用编码、分块大小、读一列的代价逐个量出来。',
    [('33.2%', '2 万条 products 列式比行式(JSON Lines)zstd-3 压缩后小的比例'), ('48.5%', '再给每列配专用编码(字典、差分、整数分)后比行式小的比例(685160 对 1331194 字节)'), ('1.3 对 57.7 ms', '只读 price 一列:列式只解压一列 与 行式解压全部再逐行解析')],
    [('为什么列式压得更小', '<p>压缩器靠找“前面出现过的相同内容”来省字节。行式里相邻的是同一条记录的不同字段(id、url、标题、价格……),彼此毫无关系;列式把同一个字段的值放在一起,url 列只剩公共前缀和递增的数字,currency 列只有两种取值,压缩器找得到很长的匹配。实验里 url 列压到 94.67×,id 列 18.01×。</p>'),
     ('哪些列压不动', '<p>title 是随机拼的词,压缩后仍要 413803 字节,占行式压缩后总量的 31.1%;price、stock、seller_id 这类没有规律的数字只有 2.3–2.4×。列式能帮上忙的是有规律的列,对本来就没规律的内容无能为力。</p>'),
     ('排列顺序', '<p>按某个字段排序,让这个字段的相似值靠在一起,行式有时能小一点(按 category 排序小 2.6%),但会打乱别的规律(列式反而大 9.4%)。排序要看哪一列是大头。</p>'),
     ('专用编码', '<p>给每列选合适的表示再压缩:id 存差分(20002 字节,压缩后 21 字节)、低基数字符串用字典、价格存整数分、时间存整数。合计 685160 字节,比行式 JSON Lines 小 48.5%。这就是列存格式(Parquet、ORC)做的事情的简化版。</p>'),
     ('分块的代价', '<p>列式的优势依赖一块里有足够多的重复:每块 100 条时只小 11.3%,5000 条时小 31.2%。要随机访问、频繁追加,块就小,列存的优势会缩水。</p>'),
     ('读一列', '<p>列式只读 price 一列,读入 49891 字节、1.3 ms;行式要解压全部 1331194 字节再逐行解析,57.7 ms。代价是写入和按行读取、更新都更麻烦,不适合每条记录频繁变化的场景。</p>')],
    steps,
    [ENV_E + '。数据集见第 1 篇;列存的专用编码是我手写的简化版(字典、差分 varint、整数分、Unix 秒),不是 Parquet 的实现,没有页、统计信息和嵌套支持;第六节是 7 次中位数,其余是确定性字节数',
     '没有验证:真实的 Parquet / ORC / Arrow 文件的体积和读取速度;不同 zstd 级别下列式的优势变化(只看了 3 和 19 的整体);嵌套和可空字段的列存表示;更新和删除的代价;列式在 sqlite 或 Redis 里的使用方式'],
    '行式与列式')
